function validate([n, edges, queries]) {
  if (!Number.isInteger(n) || n < 2 || n > 20000) return 'n is between 2 and 20000.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 100000) return 'edges needs 1 to 100000 edges.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 1 || v < 1 || u > n || v > n) return 'Edge endpoints are nodes from 1 to n.';
    if (u === v) return 'An edge must join two different nodes.';
  }
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 20) return 'queries needs 1 to 20 values.';
  if (queries.some(q => !Number.isInteger(q) || q < 0 || q >= edges.length)) return 'Each query is from 0 to edges.length - 1.';
  return null;
}

