function countPairs(n, edges, queries) {
  const degree = new Array(n + 1).fill(0);
  const shared = new Map();
  for (const [u, v] of edges) {
    degree[u]++;
    degree[v]++;
    const key = Math.min(u, v) * (n + 1) + Math.max(u, v);
    shared.set(key, (shared.get(key) || 0) + 1);
  }

  const sorted = degree.slice(1).sort((a, b) => a - b);
  const answers = [];
  for (const query of queries) {
    let count = 0;
    let left = 0;
    let right = n - 1;
    while (left < right) {
      if (sorted[left] + sorted[right] > query) {
        count += right - left;
        right--;
      } else {
        left++;
      }
    }

    for (const [key, common] of shared) {
      const a = Math.floor(key / (n + 1));
      const b = key % (n + 1);
      const total = degree[a] + degree[b];
      if (total > query && total - common <= query) {
        count--;
      }
    }
    answers.push(count);
  }
  return answers;
}

