function countPairs(n, edges, queries) {
  const incident = [];
  for (let a = 1; a <= n; a++) {
    for (let b = a + 1; b <= n; b++) {
      let touching = 0;
      for (const [u, v] of edges) {
        if (u === a || v === a || u === b || v === b) touching++;
      }
      incident.push(touching);
    }
  }
  return queries.map(q => incident.filter(value => value > q).length);
}

