function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n;
  let m;
  if (size === 'large') {
    const mode = rand();
    if (mode < 0.3) {
      n = int(20, 60);
    } else if (mode < 0.6) {
      n = int(500, 2000);
    } else {
      n = int(10000, 20000);
    }
    m = int(1500, 2000);
  } else {
    n = int(2, 7);
    m = int(1, 12);
  }
  // Some runs concentrate edges on a few hub nodes so degrees and parallel edges vary.
  const hubs = Math.max(2, Math.min(n, int(2, 6)));
  const hubChance = rand() * 0.8;
  const pick = () => (rand() < hubChance ? int(1, hubs) : int(1, n));
  const edges = [];
  const degree = new Array(n + 1).fill(0);
  while (edges.length < m) {
    const u = pick();
    const v = pick();
    if (u === v) continue;
    edges.push([u, v]);
    degree[u]++;
    degree[v]++;
  }
  const top = [...degree].sort((a, b) => b - a);
  const high = Math.min(m - 1, top[0] + top[1]);
  const q = size === 'large' ? 20 : int(1, 5);
  // Mix thresholds near the degree sum of a random pair with fully random ones.
  const near = () => Math.max(0, Math.min(m - 1, degree[int(1, n)] + degree[int(1, n)] + int(-2, 2)));
  const queries = Array.from({ length: q }, () => (rand() < 0.5 ? near() : int(0, high)));
  return [n, edges, queries];
}
